"""Stage cards, phases 1-7. Each stage follows the mandated 10-point structure."""
import calc
from calc import inr

def _h(role_activity):
    r, t = calc.labour()
    return sum(x[3] for x in r if x[0].startswith(role_activity)), sum(x[7] for x in r if x[0].startswith(role_activity))

def stages():
    mh, mc = _h("Market research"); rh, rc = _h("Requirement"); uh, uc = _h("UI/UX")
    S = []
    S.append(dict(n=1, name="Market Research & Opportunity", gate="G1 – Opportunity Approval",
     why="Prevents building a product nobody will pay for. No code is written until the owner signs G1.",
     steps=[
      "Define target market and customer segment; write the problem statement in one sentence (who, what pain, how they cope today).",
      "Interview at least 10 target customers (Customer Discovery template). Record willingness to pay as a stated price range, not a yes/no.",
      "List 5–10 competitors (direct and indirect). For each: pricing page, feature list, tech stack signals, positioning, reviews (G2, Capterra, Product Hunt, Reddit). Record URL and access date.",
      "Build the feature/pricing comparison matrix; extract gaps and the differentiator.",
      "Define Ideal Customer Profile (ICP); name buyer, end user and decision-maker (often three different people).",
      "Estimate sales cycle and acquisition difficulty (channel, effort, expected CAC range).",
      "Size the market bottom-up: TAM = all potential customers × annual contract value; SAM = reachable segment (geography, size, language); SOM = share winnable in 3 years given capacity. Show every assumption.",
      "Identify recurring-revenue levers: subscription tiers, usage add-ons, onboarding fee, support plans.",
      "Write the Market Research and Product Opportunity Report; submit for G1."],
     roles=[("Product Owner","Owns report and the go/no-go recommendation"),("Researcher / Analyst","Collects sources, builds comparison matrix"),("Business Owner","Approves or rejects at G1")],
     tools="Google Sheets/Excel, G2, Capterra, Product Hunt, Reddit, Google Trends, competitor sites, government/industry reports, interview recording (with consent).",
     time="2–3 weeks (about %d h expected for the sample product)" % mh,
     cost="Labour only: ≈ %s expected (%d h × ₹1,200). No tooling cost required." % (inr(mc), mh),
     deliver=["Market Research & Product Opportunity Report","Competitor Analysis sheet (with URLs + access dates)","Customer Discovery notes (≥10)","TAM/SAM/SOM workbook"],
     checklist=["≥5 competitors compared with source links","Every number has a source or is tagged ASSUMPTION","≥10 customer conversations logged","ICP, buyer, user, decision-maker named","TAM/SAM/SOM bottom-up with arithmetic shown","Recurring revenue path identified","Risks and kill criteria written"],
     approval="Business Owner signs G1 in the dashboard. Kill criteria: <3 of 10 prospects confirm the pain as top-3 priority, or stated willingness to pay below projected break-even price.",
     sources=[("Google Trends","https://trends.google.com/"),("G2","https://www.g2.com/"),("Capterra","https://www.capterra.com/"),("Product Hunt","https://www.producthunt.com/")],
     mistakes=[("Treating friends' enthusiasm as demand","Require stated price + a pilot commitment (LOI or paid pilot)"),("Top-down TAM ('1% of a huge market')","Use bottom-up count × price"),("Copying competitor features","Anchor on the validated pain, then differentiate")]))
    S.append(dict(n=2, name="Product Requirements & Scope Freeze", gate="G2 – Scope Freeze",
     why="Defines exactly what will be built; later change is controlled and priced.",
     steps=[
      "Write the PRD: purpose, customers, user roles and permission matrix, core modules, features/sub-features, user journeys.",
      "Write the Input–Output Specification: for every input (name, type, unit, required, default, validation, min/max, source, DB mapping) and every output (name, format, calculation, precision, display, export, API shape, error handling).",
      "Add non-functional requirements: security, performance targets, mobile responsiveness, browser matrix, backup RPO/RTO, maintenance windows.",
      "Write acceptance criteria in Given/When/Then form for every feature; attach at least one sample input→output scenario.",
      "Review with customer(s) and engineering; resolve open questions.",
      "Freeze: record version, date and approvers. All later changes go through a Change Request."],
     roles=[("Product Owner","Authors PRD, owns acceptance criteria"),("Tech Lead","Reviews feasibility, estimates, NFRs"),("QA Lead","Confirms every criterion is testable"),("Customer / Business Owner","Approves scope")],
     tools="Docs/Notion/Confluence, Figma (journey maps), spreadsheet for I/O spec, dashboard approval module.",
     time="2–3 weeks (≈ %d h)" % rh, cost="Labour: ≈ %s expected (Product Owner + Tech Lead hours)." % inr(rc),
     deliver=["Approved PRD","Input–Output Specification","Scope Freeze Document (versioned)","Change Request log (empty at freeze)"],
     checklist=["All 20 PRD headings present","Every input and output specified","Every feature has acceptance criteria","Out-of-scope list explicit","Permissions matrix complete","NFR numbers measurable (e.g. p95 < 500 ms)","Signed by customer and product owner"],
     approval="G2 signed by Product Owner and Customer. A Change Request needs: ID, business justification, technical, cost, timeline and security impact, customer approval and product-owner approval.",
     sources=[("OWASP ASVS (security requirements)","https://asvs.owasp.org/"),("NIST SP 800-218 SSDF","https://csrc.nist.gov/pubs/sp/800/218/final")],
     mistakes=[("Vague requirements ('fast', 'easy')","Write measurable targets"),("Silent scope growth","No work without a CR ID"),("Missing error-handling spec","Mandatory column in the output spec")]))
    S.append(dict(n=3, name="Technology Stack & Architecture", gate="G3 – Architecture Approval",
     why="Chooses the cheapest architecture that safely meets the requirements, with documented trade-offs.",
     steps=[
      "Draft at least two architecture options (e.g. A: Next.js + Node/TypeScript + PostgreSQL modular monolith on a managed PaaS; B: React SPA + FastAPI + PostgreSQL on a single cloud VM/containers).",
      "Score each option 1–5 on: development cost, hosting cost, maintenance cost, scalability, security, performance, developer availability, vendor lock-in, integration fit, long-term operating cost. Weight by project priorities.",
      "Default to a modular monolith for the MVP. Microservices require a written justification (independent scaling, team boundaries, compliance isolation).",
      "Produce: system diagram, frontend, backend, database architecture, ERD, API documentation (OpenAPI), authentication architecture, threat model (STRIDE), infrastructure diagram, technology justification.",
      "Run the threat model against OWASP Top 10 and ASVS level 1 (level 2 for payments/personal data).",
      "Tech Lead presents; Business Owner approves cost implications."],
     roles=[("Tech Lead","Owns the document and the decision"),("Senior Developer","Peer review and spikes"),("DevOps Engineer","Infrastructure and cost inputs"),("Product Owner","Confirms fit to requirements")],
     tools="draw.io/Excalidraw/Mermaid, dbdiagram.io or pgModeler, OpenAPI editor, threat-model template.",
     time="1–2 weeks", cost="Labour ≈ %s (Tech Lead database/API design hours in sample)." % inr(sum(x[7] for x in calc.labour()[0] if x[0].startswith("Database"))),
     deliver=["Software Architecture Document","ERD + data dictionary","OpenAPI draft","Threat model","Infrastructure diagram","Decision log (ADR)"],
     checklist=["Two options scored with weights","Modular monolith unless justified","ERD normalised and matches I/O spec","Auth, session and RBAC design written","Secrets management defined","Backups and RPO/RTO defined","Cost of each option estimated"],
     approval="G3 signed by Tech Lead and Business Owner. Any later stack change requires an ADR and a Change Request.",
     sources=[("Next.js docs","https://nextjs.org/docs"),("React docs","https://react.dev/"),("PostgreSQL docs","https://www.postgresql.org/docs/"),("OWASP","https://owasp.org/"),("AWS docs","https://docs.aws.amazon.com/"),("Vercel docs","https://vercel.com/docs")],
     mistakes=[("Choosing by hype","Use the weighted scorecard"),("Premature microservices","Modular monolith with clear module boundaries"),("No threat model","Mandatory section; reviewed at G3")]))
    S.append(dict(n=4, name="UI/UX & Prototype", gate="G4 – Design Approval",
     why="Finds usability problems when they cost hours, not weeks.",
     steps=[
      "Create sitemap and user-flow diagrams from the PRD journeys.",
      "Low-fidelity wireframes → review → high-fidelity designs in Figma.",
      "Define design system: type scale, colour tokens (with WCAG AA contrast), spacing, components, states (empty, loading, error).",
      "Design responsive layouts (mobile first; 360, 768, 1280 px).",
      "Build a clickable prototype and run a usability review with ≥5 target users; log findings and fixes.",
      "Prepare a showcase dataset using synthetic or authorised data only."],
     roles=[("UI/UX Designer","Designs, runs usability sessions"),("Product Owner","Approves flows"),("Frontend Developer","Reviews feasibility and component API"),("Customer","Approves the prototype")],
     tools="Figma, Maze/Loom for tests, axe/Lighthouse for accessibility.",
     time="2–4 weeks (≈ %d h)" % uh, cost="Labour ≈ %s (designer hours)." % inr(uc),
     deliver=["Sitemap + flows","Wireframes","Hi-fi designs","Design system / component library spec","Clickable prototype","Usability report"],
     checklist=["Every PRD journey is covered","WCAG 2.2 AA contrast for text","Keyboard and screen-reader basics considered","All states designed","No decorative animation that hurts performance","Customer sign-off recorded"],
     approval="G4 signed by Product Owner and Customer; changes after G4 follow change control.",
     sources=[("WCAG 2.2","https://www.w3.org/TR/WCAG22/"),("web.dev performance","https://web.dev/")],
     mistakes=[("Skipping error/empty states","Design-system checklist includes all states"),("Using real customer data in demos","Synthetic data only, unless authorised in writing")]))
    S.append(dict(n=5, name="VS Code, GitHub & Project Initialisation", gate="G5 – Repo Readiness",
     why="Every project starts from the same secure, automated baseline.",
     steps=[
      "Install standard tools: VS Code (with approved extensions), Git, approved Node/Python runtime and package manager, API client, DB client, browser dev tools, test runners.",
      "Create a PRIVATE GitHub repository under the company organisation; add description and README.",
      "Create the standard structure (apps/web, apps/api, packages/ui, packages/shared, docs/*, tests/{unit,integration,e2e}, infra, .github/{workflows,ISSUE_TEMPLATE}, .env.example, .gitignore, README.md, CONTRIBUTING.md).",
      "Protect main: require PR, ≥1 approving review, passing status checks, no force-push, linear history.",
      "Branches: feature/<id>-<slug>, fix/<id>-<slug>, hotfix/<id>-<slug>. Commits: Conventional Commits (feat:, fix:, docs:, chore:).",
      "CI: lint, type-check, unit tests, build, dependency audit, secret scanning, CodeQL/static analysis. Enable Dependabot.",
      "Create three environments (local, staging/preview, production) with separate databases and secrets.",
      "Tag releases with semantic versions and publish release notes."],
     roles=[("Tech Lead","Owns repo standards and branch protection"),("DevOps Engineer","CI/CD and environments"),("All developers","Follow CONTRIBUTING.md")],
     tools="VS Code, Git, GitHub (Actions, Dependabot, code scanning, secret scanning), Postman/Bruno, DBeaver/pgAdmin, Playwright/Jest/Vitest/Pytest.",
     time="2–3 days", cost="Labour ≈ 16 h DevOps; GitHub plan cost is a shared company cost (allocate by time share).",
     deliver=["Configured repository","CI pipeline green on an empty PR","CONTRIBUTING.md, PR and issue templates","Environment matrix (no secrets in the document)"],
     checklist=["Repo is private","main is protected","Secrets only in provider secret stores","CI blocks merges on failure","Dependabot + secret scanning on","Staging and production are fully separated"],
     approval="G5 signed by Tech Lead after a dry-run PR passes all checks.",
     sources=[("VS Code docs","https://code.visualstudio.com/docs"),("GitHub docs","https://docs.github.com/"),("GitHub protected branches","https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-protected-branches"),("Conventional Commits","https://www.conventionalcommits.org/")],
     mistakes=[("Committing .env or keys","Pre-commit secret scan + push protection"),("Sharing one database across environments","Separate DB and credentials per environment")]))
    S.append(dict(n=6, name="Application Development", gate="G6 – Release Candidate",
     why="Builds in small testable increments with weekly demos, never a big-bang at the end.",
     steps=[
      "Order of work: database → schema → migrations → backend structure → authentication → authorisation/roles → APIs → frontend structure → UI components → business logic → integration → file storage → email/notifications → reports/exports → payments (if required) → admin dashboard → user dashboard → error handling → logging → documentation.",
      "Every module carries: requirement reference, owner, due date, acceptance criteria, test cases, code review, documentation.",
      "Definition of Done: acceptance criteria pass; unit + integration tests added; code reviewed by someone else; no new critical lint/security findings; docs updated; demoed.",
      "Hold a working demo every week to the Product Owner using the staging environment.",
      "Track hours against estimate in the dashboard; flag >20% variance immediately.",
      "Freeze features; produce the Release Candidate; run the QA and security gates."],
     roles=[("Developers","Build and test modules"),("Tech Lead","Architecture compliance, reviews"),("QA Engineer","Test plans, regression, UAT support"),("Product Owner","Accepts or rejects each module")],
     tools="VS Code, GitHub, ORM + migrations, test frameworks, Playwright, Postman, Sentry-type error tracker.",
     time="%d–%d weeks for the sample product" % (8, 14),
     cost="Labour: frontend + backend + auth + integrations + docs ≈ %s expected." % inr(sum(x[7] for x in calc.labour()[0] if x[0].split()[0] in ("Frontend","Backend","Authentication","Integrations","Documentation"))),
     deliver=["Working software on staging","Weekly demo notes","Test reports","API documentation","Release notes"],
     checklist=["No work without a requirement reference","≥ agreed unit-test coverage on business logic","All endpoints authorised by role","Input validated server-side","Errors logged without leaking PII","Migrations reversible","Docs match behaviour"],
     approval="G6: Product Owner accepts all in-scope modules; Tech Lead certifies no open critical/high defects.",
     sources=[("OWASP Cheat Sheets","https://cheatsheetseries.owasp.org/"),("Node.js docs","https://nodejs.org/docs/"),("PostgreSQL docs","https://www.postgresql.org/docs/")],
     mistakes=[("Client-only validation","Duplicate every rule on the server"),("Merging without review","Branch protection requires ≥1 review"),("Hidden scope creep","Reject work without a requirement/CR ID")]))
    S.append(dict(n=7, name="Production Cost Calculation (mandatory)", gate="G7 – Cost Model Approval",
     why="Prevents under-pricing by costing development, launch AND operation. Never quote from domain + hosting alone.",
     steps=[
      "Labour: hours × fully loaded hourly cost per role, three scenarios (optimistic, expected via PERT = (O + 4M + P) / 6, pessimistic). Include founder time.",
      "One-time infrastructure/setup: domain, DNS, hosting, DB, email, SSL, storage, monitoring, payment gateway, backups, pipeline, legal, integrations. Mark each mandatory or optional.",
      "Monthly cost: domain, hosting, database, storage, CDN, email, SMS/WhatsApp, auth, APIs, AI, monitoring, backups, security, payment fees, maintenance, support, misc.",
      "Pull every unit price from the provider's current official pricing page; store URL + access date. If unavailable mark ASSUMPTION. Never invent a price.",
      "Capacity: model 10, 50, 100, 500, 1,000, 5,000, 10,000 users via MAU, DAU, peak concurrency, requests, queries, storage, bandwidth, emails, background jobs. Use low/medium/high scenarios if no data. Find the real bottleneck; do not multiply linearly.",
      "Cost three architectures: Lean MVP, Professional, Scalable. Report setup, monthly infra, maintenance, annual, capacity, limits, risks, upgrade triggers.",
      "Apply the formulas in section 'Financial Model' and allocate shared costs once (usage, reserved capacity or time share)."],
     roles=[("Finance Analyst / Founder","Owns the model"),("Tech Lead","Usage and capacity assumptions"),("DevOps Engineer","Provider pricing and architecture costs")],
     tools="Cost workbook (this document's model), provider pricing calculators (AWS, GCP, Azure, Vercel, Cloudflare), dashboard cost calculator.",
     time="3–5 days", cost="Labour ≈ 40 h; included in company overhead.",
     deliver=["Production Cost & SaaS Pricing Financial Model","Assumption register with source URLs","Three-model comparison"],
     checklist=["Every price has URL + date or is tagged ASSUMPTION","One-time ≠ monthly","Free tiers not treated as permanent","Shared costs counted once","Maintenance and support labour included","Optimistic/expected/pessimistic shown","Capacity bottleneck identified"],
     approval="G7 signed by Business Owner and Finance. Model is re-run on any scope change or provider price change.",
     sources=[("AWS Pricing Calculator","https://calculator.aws/"),("Vercel pricing","https://vercel.com/pricing"),("Cloudflare plans","https://www.cloudflare.com/plans/"),("Google Cloud pricing calculator","https://cloud.google.com/products/calculator"),("Azure pricing calculator","https://azure.microsoft.com/pricing/calculator/")],
     mistakes=[("Quoting only hosting","Use full formula incl. labour and support"),("Invented prices","ASSUMPTION tag or cite URL"),("Linear scaling","Use bottleneck-driven tiers")]))
    return S
